use super::*;
use openbindings::{JsonValue,NoVerdictReason,WorkControl};
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::Relaxed};
struct Stop{n:AtomicUsize,at:usize} impl WorkControl for Stop{fn is_cancelled(&self)->bool{self.n.fetch_add(1,Relaxed)>=self.at}}
#[test]fn v1_scalar_and_known_hit_need_no_pending_backing(){for text in ["null","true","123"]{let v=JsonValue::parse(text).unwrap();let c=AtomicBool::new(false);let mut values=Values::default();let mut graph=Graph::new(1<<20,None,64,&c);let s=crate::review_allocations::start();let id=values.intern(v.view(),&mut graph).unwrap();let m=crate::review_allocations::finish(s,1);assert_eq!(m["allocations_per_op"],2.0,"{text}: {m}");let s=crate::review_allocations::start();let mut g=Graph::new(0,Some(1),64,&c);assert_eq!(values.intern(v.view(),&mut g).unwrap(),id);let m2=crate::review_allocations::finish(s,1);assert_eq!(m2["allocations_per_op"],0.0);assert_eq!(values.intern(v.view(),&mut Graph::new(0,Some(0),64,&c)).unwrap_err().reason,NoVerdictReason::LimitExceeded);assert_eq!(values.intern(v.view(),&mut Graph::new(0,None,64,&AtomicBool::new(true))).unwrap_err().reason,NoVerdictReason::Cancelled);println!("scalar={text} first={m} hit={m2}");}}
#[test]fn v6_v7_cross_arena_and_postorder(){let c=AtomicBool::new(false);let mut g=Graph::new(48<<20,None,64,&c);let mut values=Values::default();let docs:Vec<_>=[r#"{"a":[1,{"b":"\ud800"}]}"#,r#"{"a":[1.0,{"b":"\ud800"}]}"#,r#"{"a":[1,{"b":"\udc00"}]}"#,r#"[{},[],{"a":"a"},[1,[2]]]"#].map(|s|JsonValue::parse(s).unwrap()).into();let a=values.intern(docs[0].view(),&mut g).unwrap();assert_eq!(a,values.intern(docs[1].view(),&mut g).unwrap());assert_ne!(a,values.intern(docs[2].view(),&mut g).unwrap());values.intern(docs[3].view(),&mut g).unwrap();assert!(values.occurrences.contains_key(&backend::occurrence(docs[3].view())));}
#[test]fn v8_partial_failure_then_retry_keeps_parent_unpublished(){let doc=JsonValue::parse(r#"{"a":[1,2,{"x":"\ud800"}],"b":[{},[],true,null,2.0]}"#).unwrap();let equal=JsonValue::parse(r#"{"b":[{},[],true,null,2],"a":[1.0,2,{"x":"\ud800"}]}"#).unwrap();let control=Stop{n:AtomicUsize::new(0),at:usize::MAX};let mut values=Values::default();values.intern(doc.view(),&mut Graph::new(48<<20,None,64,&control)).unwrap();let count=control.n.load(Relaxed);let c=AtomicBool::new(false);let mut partial=0;
 for at in 0..count{let stop=Stop{n:AtomicUsize::new(0),at};let snapshot=crate::review_allocations::start();let mut values=Values::default();let err=values.intern(doc.view(),&mut Graph::new(48<<20,None,64,&stop)).unwrap_err();assert_eq!(err.reason,NoVerdictReason::Cancelled);assert!(!values.occurrences.contains_key(&backend::occurrence(doc.view())));partial+=usize::from(!values.occurrences.is_empty());let mut g=Graph::new(48<<20,None,64,&c);let id=values.intern(doc.view(),&mut g).unwrap();assert_eq!(id,values.intern(equal.view(),&mut g).unwrap());drop(values);drop(err);drop(g);let m=crate::review_allocations::finish(snapshot,1);assert_eq!(m["baseline_live_bytes"],m["ending_live_bytes"]);}assert!(partial>0);
 let mut full=Values::default();let mut g=Graph::new(48<<20,None,64,&c);full.intern(doc.view(),&mut g).unwrap();let used=(48<<20)-g.remaining().bytes;
 for bytes in 0..used{let snapshot=crate::review_allocations::start();let mut values=Values::default();let err=values.intern(doc.view(),&mut Graph::new(bytes,None,64,&c)).unwrap_err();assert_eq!(err.reason,NoVerdictReason::LimitExceeded);assert!(!values.occurrences.contains_key(&backend::occurrence(doc.view())));let mut g=Graph::new(48<<20,None,64,&c);let id=values.intern(doc.view(),&mut g).unwrap();assert_eq!(id,values.intern(equal.view(),&mut g).unwrap());drop(values);drop(err);drop(g);let m=crate::review_allocations::finish(snapshot,1);assert_eq!(m["baseline_live_bytes"],m["ending_live_bytes"]);}
 let mut values=Values::default();let mut g=Graph::new(48<<20,Some(usize::MAX),64,&c);values.intern(doc.view(),&mut g).unwrap();let work=usize::MAX-g.remaining().work.unwrap();for limit in 0..=work{let mut values=Values::default();let r=values.intern(doc.view(),&mut Graph::new(48<<20,Some(limit),64,&c));if limit<work{assert_eq!(r.unwrap_err().reason,NoVerdictReason::LimitExceeded);assert!(!values.occurrences.contains_key(&backend::occurrence(doc.view())));}else{assert!(r.is_ok());}}println!("intern-exact-work={work}");
 println!("intern-checkpoints={count} partial={partial} reservation={used}");}
